const S={page:'overview',section:0,tasks:[],task:null,data:{records:0,devices:[],states:[],samples:[],cisco:{configured:false,connected:false},steering:{connected:false}},network:{interfaces:[],neighbors:[],wifi:{readings:[]}},device:'',metric:'',location:localStorage.getItem('netcoop-location')||'Current device location',toast:'',busy:false,scanning:false};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,opts={}){const r=await fetch('/api'+path,opts);const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function toast(msg){S.toast=msg;render();setTimeout(()=>{S.toast='';render()},4000)}
function dot(s){return `<i class="dot ${s==='Running'?'running':''}"></i>`}
function nav(){return `<aside class="sidebar" id="sidebar"><div class="brand"><div class="brand-mark">N</div><div><div class="brand-name">NetCoop AI</div><div class="brand-sub">Network operations</div></div></div><div class="nav-label">Monitor</div><button class="nav-item ${S.page==='overview'?'active':''}" data-page="overview">⌂ &nbsp;Local network overview</button><button class="nav-item ${S.page==='coverage'?'active':''}" data-page="coverage">◉ &nbsp;Signal coverage</button><button class="nav-item ${S.page==='live'?'active':''}" data-page="live">⌁ &nbsp;Live device stats</button><button class="nav-item ${S.page==='architecture'?'active':''}" data-page="architecture">⌘ &nbsp;Architecture</button><button class="nav-item ${S.page==='presentation'?'active':''}" data-page="presentation">▤ &nbsp;6-step demo guide</button><button class="nav-item ${S.page==='dashboard'?'active':''}" data-page="dashboard">▦ &nbsp;Performance trends</button><button class="nav-item ${S.page==='devices'?'active':''}" data-page="devices">⌘ &nbsp;Cached network peers</button><button class="nav-item ${S.page==='investigations'?'active':''}" data-page="investigations">◷ &nbsp;Analyze telemetry</button><div class="task-head"><div class="list-title">Recent investigations</div></div><div class="task-list">${S.tasks.map(t=>`<button class="task-row ${S.task?.id===t.id?'selected':''}" data-task="${t.id}"><div class="task-name">${esc(t.name)}</div><div class="task-meta">${dot(t.status)} ${esc(t.status)} · ${esc(t.created)}</div></button>`).join('')||'<div class="empty">No investigations yet</div>'}</div><div class="side-foot">${S.network.interfaces.length?`${S.network.interfaces.length} active interface(s) · ${S.network.neighbor_count||0} cached peers`:'Reading local network…'}<br>Peers are cache observations, not reachability checks.</div></aside>`}
function header(title,sub,right=''){return `<div class="page-header"><div><div class="eyebrow">NetCoop · Evidence-based operations</div><h1>${title}</h1><div class="sub">${sub}</div></div>${right}</div>`}
function topbar(){return `<header class="topbar"><div style="display:flex;align-items:center"><button class="mobile-menu" data-action="menu">☰</button><div class="crumb">Operations&nbsp; / &nbsp;<strong>${esc(({overview:'Network overview',coverage:'Signal coverage',live:'Live device stats',architecture:'Architecture',presentation:'6-step demo guide',dashboard:'Performance trends',devices:'Cached network peers',investigations:'Analyze telemetry',presentation:'Presentation'})[S.page])}</strong></div></div><div class="top-right"><span class="demo-badge">${S.network.interfaces.length?'● LOCAL NETWORK READ':'○ NETWORK DATA UNAVAILABLE'}</span><span class="top-user">${S.network.wifi?.last_scan?`Last Wi-Fi scan ${esc(S.network.wifi.last_scan.scanned_at)}`:'Wi-Fi scan not run'}</span></div></header>`}
function toolbar(){return `<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input id="csvFile" type="file" accept=".csv,text/csv" hidden><button class="btn" data-action="template">CSV format</button><button class="btn" data-action="cisco">${S.data.cisco?.configured?'Refresh Cisco health':'Cisco setup'}</button><button class="btn primary" data-action="import">Import telemetry CSV</button></div>`}
function stateCounts(){let a=S.data.states;return {normal:a.filter(x=>x.state==='normal').length,anomaly:a.filter(x=>x.state==='anomaly').length,unknown:a.filter(x=>x.state==='unknown').length}}
function scanControls(){return `<div class="scan-controls"><label>Spot label <input id="locationLabel" maxlength="80" value="${esc(S.location)}" placeholder="e.g. Library east wing"></label><button class="btn primary" data-action="scan" ${S.scanning?'disabled':''}>${S.scanning?'<span class="spinner"></span> Scanning Wi-Fi…':'Scan Wi-Fi here'}</button></div>`}
function savedSpotChooser(){let spots=S.network.wifi?.locations||[],selected=S.network.wifi?.last_scan?.location||S.location;return `<label class="saved-spot-label">Review saved spot <select id="savedSpot"><option value="">Latest scan</option>${spots.map(x=>`<option value="${esc(x.location)}" ${x.location===selected?'selected':''}>${esc(x.location)} · ${esc(x.scanned_at)}</option>`).join('')}</select></label>`}
function networkOverviewPage(){const n=S.network,ints=n.interfaces||[],wifi=n.wifi||{},best=wifi.best_rssi_dbm;return `<div class="page">${header('Local network overview','Live details from this computer’s active adapters and Windows neighbor cache.',`<button class="btn" data-action="refresh-network">Refresh overview</button>`)}<div class="notice ${n.interface_warning?'warn':''}"><strong>${ints.length?`${ints.length} active interface(s) found`:'Local adapter inventory unavailable'}</strong><span>${ints.length?`Captured ${esc(n.captured_at)} · ${esc(n.hostname)}. No subnet sweep was run.`:esc(n.interface_warning||'Windows returned no active interface data.')}</span></div><div class="summary-grid"><div class="sum-card"><span>Active interfaces</span><b>${ints.length}</b><small>from Windows NetworkInterface API</small></div><div class="sum-card"><span>Cached local peers</span><b>${n.neighbor_count??'—'}</b><small>not checked for current reachability</small></div><div class="sum-card"><span>Visible Wi-Fi APs</span><b>${wifi.distinct_aps??0}</b><small>${wifi.last_scan?'from last radio scan':'scan at this spot to collect'}</small></div><div class="sum-card"><span>Strongest observed AP</span><b>${best===null||best===undefined?'—':`${best} dBm`}</b><small>strongest single AP reading; RSSI is not summed</small></div></div><section class="card"><div class="card-head"><span class="card-title">Active network interfaces</span><span class="card-kicker">OS-REPORTED STATE</span></div>${ints.length?`<div class="interface-grid">${ints.map(i=>`<article class="interface-card"><div class="interface-heading"><b>${esc(i.name)}</b><span class="health">${esc(i.status)}</span></div><div class="sub">${esc(i.description)}</div><div class="interface-data"><div><small>Type</small><b>${esc(i.type)}</b></div><div><small>Adapter link rate</small><b>${esc(i.speed_mbps)} Mbps</b></div><div><small>IPv4</small><b>${(i.ipv4||[]).map(a=>`${esc(a.address)}/${esc(a.prefix)}`).join('<br>')||'Not assigned'}</b></div><div><small>Gateway</small><b>${(i.gateways||[]).map(esc).join('<br>')||'Not reported'}</b></div></div></article>`).join('')}</div>`:`<div class="empty">No active interface data is available in this session.</div>`}</section><div class="grid lower-grid"><section class="card"><div class="card-head"><span class="card-title">Observed local neighbors</span><span class="card-kicker">ARP CACHE · ${n.neighbor_count??0}</span></div>${n.neighbors?.length?`<div class="table-wrap"><table class="evidence-table"><thead><tr><th>IP address</th><th>Interface</th><th>Cache type</th><th>Reachability</th></tr></thead><tbody>${n.neighbors.map(x=>`<tr><td>${esc(x.ip)}</td><td>${esc(x.interface)}</td><td>${esc(x.cache_type)}</td><td><span class="health unknown">Not probed</span></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty">${esc(n.neighbor_warning||'Windows reports no unicast neighbors in its cache.')}</div>`}<div class="note">These are cached address-resolution entries the computer has observed; stale entries can remain after a device disconnects. This overview does not probe the subnet.</div></section><section class="card"><div class="card-head"><span class="card-title">Wi-Fi at a named spot</span><span class="card-kicker">LOCAL RADIO SCAN</span></div><div class="card-body">${scanControls()}<p class="note">Scan reads nearby access-point beacons at this computer’s physical location. The label is user-entered; it does not identify a room automatically.</p>${wifi.last_scan?`<div class="note">Last scan: ${esc(wifi.last_scan.location)} · ${esc(wifi.last_scan.scanned_at)} · ${esc(wifi.interface||'')}</div>${signalCards(wifi.readings||[])}`:'<div class="empty">No Wi-Fi survey has been run yet.</div>'}</div></section></div></div>`}
function signalCards(readings){if(!readings.length)return '<div class="empty">The WLAN scan returned no access-point readings.</div>';return `<div class="signal-list">${readings.map((x,i)=>`<article class="signal-row" tabindex="0" title="${esc(x.ssid)} · ${esc(x.rssi_dbm)} dBm"><div class="signal-rank">${String(i+1).padStart(2,'0')}</div><div class="signal-main"><b>${esc(x.ssid)}</b><small>${esc(x.bssid)} · ${esc(x.frequency_khz/1000)} MHz</small><div class="signal-meter"><i style="width:${Math.max(0,Math.min(100,x.signal_quality))}%"></i></div></div><div class="signal-values"><b>${esc(x.rssi_dbm)} dBm</b><small>${esc(x.signal_quality)}% driver quality</small></div></article>`).join('')}</div>`}
function coveragePage(){const w=S.network.wifi||{},r=w.readings||[],best=r.reduce((a,x)=>!a||x.rssi_dbm>a.rssi_dbm?x:a,null);return `<div class="page">${header('Signal coverage at a spot','Compare real AP RSSI readings from this computer’s current physical location.',scanControls())}<div class="notice"><strong>Spot: ${esc(w.last_scan?.location||S.location)}</strong><span>${w.last_scan?`Surveyed ${esc(w.last_scan.scanned_at)} on ${esc(w.interface||'the active Wi-Fi adapter')}.`:'Run a Wi-Fi scan after placing this computer at the target location.'} Readings are local to this machine and are not sent to a third party.</span></div><div class="spot-review">${savedSpotChooser()}</div><div class="summary-grid"><div class="sum-card"><span>Access points observed</span><b>${w.distinct_aps??r.length}</b><small>unique BSSIDs in the scan</small></div><div class="sum-card"><span>Best single AP</span><b>${best?`${best.rssi_dbm} dBm`:'—'}</b><small>${best?esc(best.ssid):'No measurement yet'}</small></div><div class="sum-card"><span>Other overlapping APs</span><b>${Math.max(0,r.length-(best?1:0))}</b><small>individual signals shown below</small></div><div class="sum-card"><span>Combined RSSI</span><b>Not summed</b><small>independent AP dBm values do not add into usable client signal</small></div></div><section class="card"><div class="card-head"><span class="card-title">Signal readings at ${esc(w.last_scan?.location||S.location)}</span><span class="card-kicker">SOURCE: WINDOWS WLAN BSS SCAN</span></div><div class="card-body">${r.length?signalCards(r):'<div class="empty">No scan results. Move the computer to the desired spot, set its label above, and scan.</div>'}<div class="note">Wi-Fi clients associate to an access point; RSSI from separate APs cannot be added to create stronger service. This view combines measurements as a coverage survey: strongest measured AP plus the overlapping alternatives. AP placement or mesh backhaul changes require a network controller and real topology.</div></div></section></div>`}
function dashboard(){const c=stateCounts(),dev=S.data.devices,health=S.data.service_health?.devices||[],score=health.length?Math.round(health.reduce((a,x)=>a+(x.score??0),0)/health.length):null,coverage=health.length?Math.round(health.reduce((a,x)=>a+x.coverage,0)/health.length*100):0;return `<div class="page">${header('Network performance','Normal readings are monitored without intervention. Deviations are flagged against empirical history.',toolbar())}<div class="notice ${c.anomaly?'warn':''}"><strong>${S.data.records?c.anomaly?`${c.anomaly} deviation(s) detected`:'Monitoring imported telemetry': 'No data source connected'}</strong><span>${S.data.records?c.anomaly?'No routing changes were made. Automatic steering is inactive until a real controller and its policy are configured.':`${c.normal} metric group(s) within baseline · ${c.unknown} unclassified`: 'Import timestamped measurements or connect an approved telemetry collector. The dashboard will not invent device status or metrics.'}</span></div><div class="summary-grid"><div class="sum-card"><span>Service health score</span><b>${score===null?"—":`${score}/100`}</b><small>${score===null?"No service telemetry":"Observed coverage "+coverage+"% · uncalibrated"}</small></div><div class="sum-card"><span>Devices observed</span><b>${dev.length}</b><small>from imported telemetry</small></div><div class="sum-card"><span>Within baseline</span><b>${c.normal}</b><small>history-backed metrics</small></div><div class="sum-card ${c.anomaly?'alert':''}"><span>Deviations</span><b>${c.anomaly}</b><small>requires investigation</small></div><div class="sum-card"><span>Unclassified</span><b>${c.unknown}</b><small>insufficient history</small></div></div><div class="grid"><section class="card"><div class="card-head"><span class="card-title">Telemetry trend</span><span class="card-kicker">SOURCE-OBSERVED VALUES</span></div><div class="card-body">${chartControls()}${chart()}</div></section><section class="card"><div class="card-head"><span class="card-title">Device health</span><span class="card-kicker">LATEST REPORTED VALUES</span></div>${deviceTable(dev)}</section></div><div class="grid lower-grid"><section class="card"><div class="card-head"><span class="card-title">Anomaly response policy</span><span class="card-kicker">READ-ONLY UNTIL CONFIGURED</span></div><div class="card-body"><div class="policy-row"><span class="policy-num">01</span><div><b>Compare against device history</b><p>At least 20 prior readings are required for a robust median/MAD baseline. Without one, the reading is marked unknown.</p></div></div><div class="policy-row"><span class="policy-num">02</span><div><b>Normal range → no action</b><p>Measurements within the empirical baseline remain monitored. No route or hardware setting is changed.</p></div></div><div class="policy-row"><span class="policy-num">03</span><div><b>Deviation → investigate, then steer only when safe</b><p>A controller must confirm alternate-path capacity and pass configured operating limits before any traffic shift can be applied.</p></div></div></div></section><section class="card"><div class="card-head"><span class="card-title">Traffic steering</span><span class="card-kicker">${S.data.steering?.connected?'CONNECTED':'NOT CONFIGURED'}</span></div><div class="card-body"><div class="steer-state">${S.data.steering?.connected?'Controller adapter connected':'No SDN / SD-WAN controller attached'}</div><p class="sub">No production traffic has been diverted. To enable automatic load shifting, connect the actual telemetry source and controller API, define capacity and hardware safety limits, and verify route changes from returned telemetry.</p><div class="note">A 200 GB transfer alone is not evidence of congestion. Steering requires observed path utilization, candidate-path headroom, and live controller confirmation.</div></div></section></div></div>`}
function chartControls(){let metrics=[...new Set(S.data.samples.map(x=>x.metric))];let devs=[...new Set(S.data.samples.map(x=>x.device_id))];if(!S.device&&devs.length)S.device=devs[0];if(!S.metric&&metrics.length)S.metric=metrics[0];return `<div class="chart-controls"><label>Device <select id="chartDevice">${devs.map(d=>`<option ${d===S.device?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label>Metric <select id="chartMetric">${metrics.map(d=>`<option ${d===S.metric?'selected':''}>${esc(d)}</option>`).join('')}</select></label><span class="chart-unit">Imported observations only</span></div>`}
function chart(){let rows=S.data.samples.filter(x=>x.device_id===S.device&&x.metric===S.metric&&typeof x.value==='number').slice(-80);if(rows.length<2)return `<div class="chart-empty">${S.data.records?'Need at least two numeric observations for a trend line.':'Trend graph appears after telemetry is imported.'}</div>`;let vals=rows.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,pts=vals.map((v,i)=>`${30+i*(620/(vals.length-1))},${195-(v-min)/span*150}`).join(' ');return `<svg class="chart-svg" viewBox="0 0 680 240" role="img" aria-label="${esc(S.metric)} observations for ${esc(S.device)}"><line x1="30" y1="195" x2="650" y2="195" stroke="#dfe6e9"/><line x1="30" y1="45" x2="30" y2="195" stroke="#dfe6e9"/><polyline points="${pts}" fill="none" stroke="#16786e" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${rows.map((r,i)=>`<circle cx="${30+i*(620/(vals.length-1))}" cy="${195-(r.value-min)/span*150}" r="${i===rows.length-1?4:2}" fill="${i===rows.length-1?'#bb5148':'#16786e'}"><title>${esc(r.timestamp)} · ${r.value} ${esc(r.unit)}</title></circle>`).join('')}<text x="32" y="222">${esc(rows[0].timestamp)}</text><text x="550" y="222">${esc(rows.at(-1).timestamp)}</text><text x="34" y="38">${max} ${esc(rows[0].unit)}</text><text x="34" y="190">${min}</text></svg>`}
function deviceTable(devs){if(!devs.length)return '<div class="empty">No devices observed. Import telemetry with device_id values to populate this panel.</div>';return `<div class="table-wrap"><table class="evidence-table"><thead><tr><th>Device</th><th>Reported health</th><th>Latest metrics</th><th>Last observation</th></tr></thead><tbody>${devs.map(d=>{let health=d.metrics.device_status?.value;let state=S.data.states.filter(x=>x.device_id===d.device_id);let abnormal=state.some(x=>x.state==='anomaly');return `<tr><td><b>${esc(d.device_id)}</b>${d.parent_device_id?`<small class="cell-sub">Parent: ${esc(d.parent_device_id)}</small>`:''}</td><td>${health?`<span class="health ${String(health).toLowerCase()}">${esc(health)}</span>`:'<span class="health unknown">Not reported</span>'}${abnormal?'<small class="cell-sub danger-text">Metric deviation</small>':''}</td><td>${Object.entries(d.metrics).filter(([k])=>k!=='device_status').slice(0,4).map(([k,v])=>`<span class="metric-chip">${esc(k)} <b>${esc(v.value)} ${esc(v.unit)}</b></span>`).join('')||'—'}</td><td>${esc(d.latest_timestamp)}</td></tr>`}).join('')}</tbody></table></div>`}
function devicesPage(){const peers=S.network.neighbors||[],dev=S.data.devices||[],edges=dev.filter(d=>d.parent_device_id);return `<div class="page">${header('Network devices and topology','Peer addresses are from Windows cache; topology links appear only when a data source supplies parent relationships.')}<div class="notice"><strong>${peers.length} cached address entries · ${dev.length} telemetry devices</strong><span>Cached addresses may be stale and are not probed. Device status and topology are shown only when a connected source reports them.</span></div><section class="card"><div class="card-head"><span class="card-title">Reported topology</span><span class="card-kicker">SUPPLIED RELATIONSHIPS ONLY</span></div><div class="card-body">${edges.length?`<div class="topology-tree">${edges.map(d=>`<div class="topology-edge"><div class="topology-node"><b>${esc(d.parent_device_id)}</b><small>reported parent</small></div><span class="arch-arrow">→</span><button class="topology-node" data-device="${esc(d.device_id)}"><b>${esc(d.device_id)}</b><small>${Object.keys(d.metrics).length} reported metrics · click to inspect</small></button></div>`).join('')}</div>`:'<div class="empty">No topology edges have been supplied. Import parent_device_id with telemetry or connect a controller that reports device relationships.</div>'}<div class="note">No Internet, router, modem, switch, AP, or server node is invented. If your source does not identify a hop, it remains unknown.</div></div></section><section class="card" style="margin-top:16px"><div class="card-head"><span class="card-title">Cached local peers</span><span class="card-kicker">WINDOWS NEIGHBOR CACHE · ${peers.length}</span></div>${peers.length?`<div class="table-wrap"><table class="evidence-table"><thead><tr><th>Address</th><th>Interface</th><th>Cache type</th><th>Status</th></tr></thead><tbody>${peers.map(p=>`<tr><td>${esc(p.ip)}</td><td>${esc(p.interface)}</td><td>${esc(p.cache_type)}</td><td><span class="health unknown">Not confirmed</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No cached peer entries were reported by Windows.</div>'}</section><section class="card" style="margin-top:16px"><div class="card-head"><span class="card-title">Telemetry devices and health</span><span class="card-kicker">${dev.length} REPORTED</span></div>${dev.length?deviceTable(dev):'<div class="card-body"><div class="empty">No per-device metrics are connected yet. Import a real telemetry export to populate this list.</div></div>'}</section></div>`}function investigations(){return `<div class="page">${header('Analyze telemetry','Run an evidence review on imported or controller-supplied readings. This does not inspect every cached device or change network routes.') }<div class="grid"><section class="card"><div class="card-head"><span class="card-title">Inspect network conditions</span><span class="card-kicker">LOCAL ANALYSIS</span></div><div class="card-body"><form id="diagnoseForm"><label class="field-label" for="issue">Question or scope</label><textarea id="issue" class="request-input" maxlength="1200" placeholder="For example: check whether latency is deviating on the core path."></textarea><button class="btn primary" type="submit" ${S.busy?'disabled':''}>${S.busy?'Analyzing…':'Analyze available telemetry →'}</button></form><div class="suggestions"><button class="chip" data-fill="Check whether any device metrics are outside their historical baseline.">Check for deviations</button><button class="chip" data-fill="Review hardware performance and device health from the imported readings.">Review device health</button></div></div></section><section class="card"><div class="card-head"><span class="card-title">Execution record</span></div><div class="card-body">${S.task?`<div class="timeline">${S.task.events.map(e=>`<div class="event"><div class="event-rail"><span class="event-dot done"></span></div><div><div class="event-name">${esc(e.name)}</div><div class="event-detail">${esc(e.detail)}</div><div class="event-tool">${esc(e.tool)}</div></div><div class="event-time">${esc(e.time)}</div></div>`).join('')}</div>`:'<div class="empty">Start an analysis to view its execution record.</div>'}</div></section></div>${S.task?.result?resultCard(S.task.result):''}</div>`}
function resultCard(r){return `<section class="card report"><div class="card-head"><span class="card-title">Analysis result</span><span class="card-kicker">${esc(r.status)}</span>${r.json_report?`<a class="btn" href="/api/tasks/${esc(S.task?.id)}/report.json">Download JSON report</a>`:""}</div><div class="card-body">${r.demo_data?`<div class="notice warn"><strong>SYNTHETIC DEMO DATA</strong><span>This scenario is generated for demonstration and does not describe your network.</span></div>`:""}<div class="cause">${esc(r.title)}</div><div class="report-summary">${esc(r.summary)}</div>${r.json_report?`<div class="confidence"><b>Probable cause:</b> ${esc(r.json_report.suspected_root_cause)} · ${esc(r.json_report.confidence_category)} confidence <span>(rule-based, not calibrated)</span></div>`:""}<div class="confidence">${esc(r.confidence)} · Evidence coverage: ${esc(r.coverage??'not assessed')}</div>${r.evidence?.length?`<table class="evidence-table" style="margin-top:14px"><thead><tr><th>Device</th><th>Metric</th><th>Latest</th><th>Baseline score</th><th>State</th></tr></thead><tbody>${r.evidence.map(x=>`<tr><td>${esc(x.device_id)}</td><td>${esc(x.metric)}</td><td>${esc(x.value)} ${esc(x.unit)}</td><td>${x.score===null?'—':esc(x.score)}</td><td>${esc(x.state)}</td></tr>`).join('')}</tbody></table>`:''}${r.agent_findings?.length?`<h3 class="subhead">Collaborating diagnostic agents</h3><div class="agent-grid">${r.agent_findings.map(f=>`<div class="arch-detail"><strong>${esc(f.agent)}</strong><span class="agent-status">${esc(f.status)}</span><p>${Array.isArray(f.observations)?`${f.observations.length} metric finding(s) returned.`:`${f.observations.observed_devices?.length||0} devices and ${f.observations.observed_parent_edges?.length||0} supplied topology edge(s) returned.`}</p></div>`).join('')}</div><details class="message-log"><summary>NetCoop Message Protocol v1 trace</summary><pre>${esc(JSON.stringify(r.message_log,null,2))}</pre></details>`:''}<div class="recommend"><b>Next step</b><br>${esc(r.recommendation)}</div></div></section>`}
function architecturePage(){return `<div class="page">${header('How NetCoop works','The architecture below describes the code that is running now, including its read-only limits.')}<section class="card"><div class="card-head"><span class="card-title">Request to evidence-based report</span><span class="card-kicker">CURRENT IMPLEMENTATION</span></div><div class="card-body"><div class="arch">${['Dashboard request','Python request validator','Orchestrator','Performance agent','Infrastructure agent','Connectivity agent','Correlation rules','Report validator','JSON report'].map((x,i)=>`${i?'<div class="arch-arrow">→</div>':''}<div class="arch-box">${x}</div>`).join('')}</div><p class="note">Agents are deterministic local Python handlers. The orchestrator validates their messages and the report before displaying results; this build has no language model in its decision path.</p></div></section><div class="grid lower-grid"><section class="card"><div class="card-head"><span class="card-title">Agents and messages</span><span class="card-kicker">NCMP / 1.0</span></div><div class="card-body"><div class="policy-row"><span class="policy-num">01</span><div><b>Performance agent</b><p>Reads latency, jitter, packet loss, throughput, utilization, and signal measurements.</p></div></div><div class="policy-row"><span class="policy-num">02</span><div><b>Infrastructure health agent</b><p>Reads CPU, memory, interface errors, queue drops, service status, and pool metrics.</p></div></div><div class="policy-row"><span class="policy-num">03</span><div><b>Connectivity agent</b><p>Reads only supplied device IDs, parent relationships, and affected-device scope.</p></div></div><div class="policy-row"><span class="policy-num">04</span><div><b>Correlation and reporting</b><p>Ranks documented evidence patterns, retains competing causes, and validates the required JSON report fields.</p></div></div><div class="note">Messages use a versioned JSON envelope. The current transport is in-process; it is not a separate HTTP agent network.</div></div></section><section class="card"><div class="card-head"><span class="card-title">Data sources and controls</span><span class="card-kicker">ACTUAL SOURCES ONLY</span></div><div class="card-body"><div class="policy-row"><span class="policy-num">OS</span><div><b>Windows local reads</b><p>Interface counters, CPU/memory, neighbor cache, and explicit WLAN surveys describe this computer only.</p></div></div><div class="policy-row"><span class="policy-num">CSV</span><div><b>Validated telemetry import</b><p>Timestamp, device, metric, value, unit, and source are required. Missing fields and incompatible units are rejected.</p></div></div><div class="policy-row"><span class="policy-num">API</span><div><b>Optional Cisco SD-WAN health</b><p>A server-side read-only account can retrieve hardware status, CPU, and memory. It does not provide route utilization or change paths.</p></div></div><div class="note">SQLite stores submitted telemetry, tasks, reports, and Wi-Fi survey history. Secrets stay in server environment variables. The HTTP server binds to localhost; remote users need a separate authenticated HTTPS deployment.</div></div></section></div><section class="card" style="margin-top:16px"><div class="card-head"><span class="card-title">What is not connected</span><span class="card-kicker">NO GUESSED PATHS</span></div><div class="card-body"><p>No router, modem, AP-client, DNS, DHCP, database, or application-pool status is inferred from this laptop's counters. Such diagnoses appear only when an authorized source supplies those device and service metrics. No production route or hardware setting is changed.</p></div></section></div>`}
const presentationSections=['Problem & introduction','Our solution','System architecture','Live demonstration','Technical decisions & reliability','Results & conclusion'];
function presentation(){let card=[`<h2>Why network faults are difficult</h2><p>Latency, loss, device health, and topology may come from different sources. NetCoop keeps each measurement's source and unit and reports uncertainty when evidence is missing.</p>`,`<h2>Specialized agents share evidence</h2><p>Performance, infrastructure, and connectivity roles analyze separate evidence slices. A correlation role compares supported fault patterns, and the reporting role validates one structured result.</p><div class="note">The roles are deterministic in-process Python handlers, not independent cloud agents or LLMs.</div>`,`<h2>System architecture</h2><p>Open the Architecture page for the live request flow, message envelope, data sources, and limits.</p><button class="btn primary" data-page="architecture">Open architecture →</button>`,`<h2>Run a demonstration</h2><p>For a live-data run, open Live device stats and then submit a telemetry investigation. If no network source is connected, run the separate synthetic fixture from a terminal: <code>python demo.py link_congestion</code>. It prints a labeled JSON report and never inserts sample values into the live database.</p><button class="btn" data-page="live">Show live local measurements</button> <button class="btn" data-page="investigations">Run an investigation</button> <button class="btn primary" data-action="demo" data-scenario="link_congestion">Run labeled congestion demo</button>`,`<h2>Technical choices and reliability</h2><p>Python standard library handles the local HTTP service, SQLite, validation, and orchestration; plain JavaScript and CSS render the dashboard without a frontend build step.</p><p>Imports require timestamps, units, and sources. Missing and incompatible data are reported. The detector needs 20 prior observations. Confidence is a documented, uncalibrated rule score.</p><p>Automated routing is disabled. Use a read-only controller account; keep credentials server-side.</p>`,`<h2>Results and current limits</h2><div class="metric-cards"><div class="metric-card"><b>${S.data.records}</b><span>Source observations stored</span></div><div class="metric-card"><b>${S.data.devices.length}</b><span>Devices supplied by telemetry</span></div><div class="metric-card"><b>Not yet evaluated</b><span>Real-world diagnostic accuracy</span></div><div class="metric-card"><b>Not connected</b><span>Automatic traffic steering</span></div></div><p>Each completed investigation has an evidence trace and downloadable JSON report. No benchmark accuracy or live router diagnosis is claimed until measured against labeled network data and a real telemetry controller.</p>`][S.section||0];return `<div class="page">${header('6-step demo guide',`Section ${(S.section||0)+1} of 6 · This is the presentation guide, separate from live monitoring.`)}<nav class="section-tabs">${presentationSections.map((x,i)=>`<button class="section-tab ${S.section===i?'active':''}" data-section="${i}">${String(i+1).padStart(2,'0')} &nbsp;${x}</button>`).join('')}</nav><section class="card content-card">${card}<div style="display:flex;justify-content:space-between;margin-top:24px;padding-top:14px;border-top:1px solid var(--line)"><button class="btn" data-section="${Math.max(0,(S.section||0)-1)}">← Previous</button><span class="card-kicker">${(S.section||0)+1} / 6</span><button class="btn primary" data-section="${Math.min(5,(S.section||0)+1)}">Next section →</button></div></section></div>`}function render(){let pages={overview:networkOverviewPage,coverage:coveragePage,live:livePage,architecture:architecturePage,presentation,dashboard,devices:devicesPage,investigations};let content=(pages[S.page]||networkOverviewPage)();document.getElementById('root').innerHTML=`<div class="shell">${nav()}<main class="main">${topbar()}${content}</main>${S.toast?`<div class="toast">${esc(S.toast)}</div>`:''}</div>`;bind()}
async function refresh(){try{S.data=await api('/telemetry');S.tasks=await api('/tasks');if(S.task){let t=S.tasks.find(x=>x.id===S.task.id);if(t)S.task=t}render()}catch(e){toast(e.message)}}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;render()});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{S.section=+b.dataset.section;S.page='presentation';render()});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{try{S.task=await api('/tasks/'+b.dataset.task);S.page='investigations';render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-fill]').forEach(b=>b.onclick=()=>{document.getElementById('issue').value=b.dataset.fill});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.dataset.action==='menu')document.getElementById('sidebar').classList.toggle('open');if(b.dataset.action==='template'){const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,timestamp%2Cdevice_id%2Cmetric%2Cvalue%2Cunit%2Csource%2Cparent_device_id%2Cpath_id%0A';a.download='netcoop-telemetry-template.csv';a.click()}if(b.dataset.action==='import')document.getElementById('csvFile').click();if(b.dataset.action==='demo'){b.disabled=true;b.textContent='Running synthetic scenario…';try{const d=await api('/demo/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:b.dataset.scenario})});S.task=d;S.page='investigations';await refresh();S.task=d;render()}catch(e){b.disabled=false;b.textContent='Run labeled congestion demo';toast(e.message)}}if(b.dataset.action==='cisco'){if(!S.data.cisco?.configured)return toast('Cisco Manager is not configured. Set its HTTPS URL and credentials as server-side environment variables.');b.disabled=true;b.textContent='Reading…';try{const d=await api('/cisco/refresh',{method:'POST'});await refresh();toast(`Cisco Manager returned ${d.imported} device-health measurements.`)}catch(e){toast(e.message)}}});let f=document.getElementById('csvFile');if(f)f.onchange=async()=>{if(!f.files?.length)return;let file=f.files[0];try{let resp=await fetch('/api/telemetry/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:await file.text()});let d=await resp.json();if(!resp.ok)throw Error(d.error);await refresh();toast(`Imported ${d.imported} records; rejected ${d.rejected}.`)}catch(e){toast(e.message)}f.value=''};for(const id of ['chartDevice','chartMetric']){const el=document.getElementById(id);if(el)el.onchange=()=>{if(id==='chartDevice')S.device=el.value;else S.metric=el.value;render()}}document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{S.device=b.dataset.device;S.page='dashboard';render()});let form=document.getElementById('diagnoseForm');if(form)form.onsubmit=async e=>{e.preventDefault();let request=document.getElementById('issue').value.trim();if(!request)return toast('Enter the scope you want analyzed.');try{S.busy=true;render();let d=await api('/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request})});for(let i=0;i<12;i++){await new Promise(r=>setTimeout(r,120));S.task=await api('/tasks/'+d.id);if(S.task.status!=='Running')break}S.busy=false;await refresh();S.page='investigations';render()}catch(err){S.busy=false;render();toast(err.message)}}}
function chart(){let rows=S.data.samples.filter(x=>x.device_id===S.device&&x.metric===S.metric&&typeof x.value==='number').slice(-80);if(rows.length<2)return `<div class="chart-empty">${S.data.records?'Need at least two numeric observations for a trend line.':'No performance observations loaded. Use the local overview for live interface and Wi-Fi data.'}</div>`;let vals=rows.map(x=>x.value),min=Math.min(...vals),max=Math.max(...vals),span=max-min||1,coords=vals.map((v,i)=>({x:30+i*(620/(vals.length-1)),y:195-(v-min)/span*150})),pts=coords.map(p=>`${p.x},${p.y}`).join(' ');return `<div class="chart-frame"><svg class="chart-svg" viewBox="0 0 680 240" role="img" aria-label="${esc(S.metric)} observations for ${esc(S.device)}"><line x1="30" y1="195" x2="650" y2="195" stroke="#dfe6e9"/><line x1="30" y1="45" x2="30" y2="195" stroke="#dfe6e9"/><polyline points="${pts}" fill="none" stroke="#16786e" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>${coords.map((p,i)=>`<circle class="chart-point" cx="${p.x}" cy="${p.y}" r="${i===rows.length-1?4:2}" fill="${i===rows.length-1?'#bb5148':'#16786e'}" data-tip="${esc(rows[i].timestamp)} · ${esc(rows[i].value)} ${esc(rows[i].unit)}"/>`).join('')}<line id="chartCursor" x1="0" y1="45" x2="0" y2="195" stroke="#85989a" stroke-dasharray="3 3" visibility="hidden"/><text x="32" y="222">${esc(rows[0].timestamp)}</text><text x="550" y="222">${esc(rows.at(-1).timestamp)}</text><text x="34" y="38">${max} ${esc(rows[0].unit)}</text><text x="34" y="190">${min}</text></svg><div id="chartTip" class="chart-tooltip" aria-live="polite"></div></div>`}
async function refresh(){try{S.data=await api('/telemetry');S.tasks=await api('/tasks');if(S.task){let t=S.tasks.find(x=>x.id===S.task.id);if(t)S.task=t}render()}catch(e){toast(e.message)}}
async function loadNetwork(){try{S.network=await api('/network/overview');render()}catch(e){S.network={...S.network,interface_warning:e.message};render()}}
async function runWifiScan(){let field=document.getElementById('locationLabel');if(field)S.location=field.value.trim()||'Current device location';localStorage.setItem('netcoop-location',S.location);S.scanning=true;render();try{const result=await api('/network/scan',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:S.location})});S.network=await api('/network/overview');toast(`Wi-Fi scan recorded ${result.readings} access-point reading(s) at “${result.location}”.`)}catch(e){toast(e.message)}finally{S.scanning=false;render()}}
function render(){let content=S.page==='overview'?networkOverviewPage():S.page==='coverage'?coveragePage():S.page==='live'?livePage():S.page==='architecture'?architecturePage():S.page==='dashboard'?dashboard():S.page==='devices'?devicesPage():S.page==='investigations'?investigations():presentation();document.getElementById('root').innerHTML=`<div class="shell">${nav()}<main class="main">${topbar()}${content}</main>${S.toast?`<div class="toast">${esc(S.toast)}</div>`:''}</div>`;bind();let spot=document.getElementById('savedSpot');if(spot)spot.onchange=async()=>{try{S.network=await api('/network/overview?location='+encodeURIComponent(spot.value));if(S.network.wifi.last_scan)S.location=S.network.wifi.last_scan.location;render()}catch(e){toast(e.message)}}}
function bind(){document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{S.page=b.dataset.page;render()});document.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>{S.section=+b.dataset.section;S.page='presentation';render()});document.querySelectorAll('[data-task]').forEach(b=>b.onclick=async()=>{try{S.task=await api('/tasks/'+b.dataset.task);S.page='investigations';render()}catch(e){toast(e.message)}});document.querySelectorAll('[data-fill]').forEach(b=>b.onclick=()=>{let f=document.getElementById('issue');if(f)f.value=b.dataset.fill});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=async()=>{if(b.dataset.action==='menu')document.getElementById('sidebar').classList.toggle('open');if(b.dataset.action==='demo'){try{let d=await api('/demo/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:b.dataset.scenario||'link_congestion'})});S.task=d;S.tasks=await api('/tasks');S.page='investigations';render()}catch(e){toast(e.message)}}if(b.dataset.action==='scan')runWifiScan();if(b.dataset.action==='refresh-network')loadNetwork();if(b.dataset.action==='template'){const a=document.createElement('a');a.href='data:text/csv;charset=utf-8,timestamp%2Cdevice_id%2Cmetric%2Cvalue%2Cunit%2Csource%2Cparent_device_id%2Cpath_id%0A';a.download='netcoop-telemetry-template.csv';a.click()}if(b.dataset.action==='import')document.getElementById('csvFile').click();if(b.dataset.action==='demo'){b.disabled=true;b.textContent='Running synthetic scenario…';try{const d=await api('/demo/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scenario:b.dataset.scenario})});S.task=d;S.page='investigations';await refresh();S.task=d;render()}catch(e){b.disabled=false;b.textContent='Run labeled congestion demo';toast(e.message)}}if(b.dataset.action==='cisco'){if(!S.data.cisco?.configured)return toast('Cisco Manager is not configured. Set its HTTPS URL and credentials as server-side environment variables.');b.disabled=true;b.textContent='Reading…';try{const d=await api('/cisco/refresh',{method:'POST'});await refresh();toast(`Cisco Manager returned ${d.imported} device-health measurements.`)}catch(e){toast(e.message)}}});let loc=document.getElementById('locationLabel');if(loc)loc.onchange=()=>{S.location=loc.value.trim()||'Current device location';localStorage.setItem('netcoop-location',S.location)};let f=document.getElementById('csvFile');if(f)f.onchange=async()=>{if(!f.files?.length)return;let file=f.files[0];try{let resp=await fetch('/api/telemetry/import',{method:'POST',headers:{'Content-Type':'text/csv'},body:await file.text()});let d=await resp.json();if(!resp.ok)throw Error(d.error);await refresh();toast(`Imported ${d.imported} records; rejected ${d.rejected}.`)}catch(e){toast(e.message)}f.value=''};for(const id of ['chartDevice','chartMetric']){const el=document.getElementById(id);if(el)el.onchange=()=>{if(id==='chartDevice')S.device=el.value;else S.metric=el.value;render()}}const svg=document.querySelector('.chart-svg'),line=document.getElementById('chartCursor'),tip=document.getElementById('chartTip');if(svg&&line&&tip){svg.onpointermove=e=>{const rect=svg.getBoundingClientRect(),x=(e.clientX-rect.left)/rect.width*680,pts=[...svg.querySelectorAll('.chart-point')];if(!pts.length)return;const point=pts.reduce((a,b)=>Math.abs(+b.getAttribute('cx')-x)<Math.abs(+a.getAttribute('cx')-x)?b:a);line.setAttribute('x1',point.getAttribute('cx'));line.setAttribute('x2',point.getAttribute('cx'));line.setAttribute('visibility','visible');tip.textContent=point.dataset.tip;tip.style.display='block'};svg.onpointerleave=()=>{line.setAttribute('visibility','hidden');tip.style.display='none'}}document.querySelectorAll('[data-device]').forEach(b=>b.onclick=()=>{S.device=b.dataset.device;S.page='dashboard';render()});let form=document.getElementById('diagnoseForm');if(form)form.onsubmit=async e=>{e.preventDefault();let request=document.getElementById('issue').value.trim();if(!request)return toast('Enter the scope you want analyzed.');try{S.busy=true;render();let d=await api('/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({request})});for(let i=0;i<12;i++){await new Promise(r=>setTimeout(r,120));S.task=await api('/tasks/'+d.id);if(S.task.status!=='Running')break}S.busy=false;await refresh();S.page='investigations';render()}catch(err){S.busy=false;render();toast(err.message)}}}
async function loadLive(){try{S.live=await api('/network/live');if(S.page==='live')render()}catch(e){S.live={error:e.message,history:[]};if(S.page==='live')render()}}
function livePage(){const hist=(S.live?.history||[]).filter(x=>!x.error),latest=hist.at(-1)||{},ifs=latest.interfaces||[],rx=ifs.reduce((a,x)=>a+x.rx_mbps,0),tx=ifs.reduce((a,x)=>a+x.tx_mbps,0),fmt=x=>x==null?'—':`${x}%`,rate=x=>{const bps=Math.max(0,x*1e6);if(bps>=1e9)return `${(bps/1e9).toFixed(2)} Gbps`;if(bps>=1e6)return `${(bps/1e6).toFixed(2)} Mbps`;if(bps>=1e3)return `${(bps/1e3).toFixed(1)} Kbps`;return `${bps.toFixed(0)} bps`},pts=key=>{if(hist.length<2)return '';const vals=hist.map(x=>x[key]??0);return vals.map((v,i)=>`${30+i*620/(vals.length-1)},${170-Math.max(0,Math.min(100,v))*1.35}`).join(' ')},traffic=hist.map(h=>({rx:(h.interfaces||[]).reduce((a,x)=>a+x.rx_mbps,0),tx:(h.interfaces||[]).reduce((a,x)=>a+x.tx_mbps,0)})),tmax=Math.max(.001,...traffic.flatMap(x=>[x.rx,x.tx])),tpts=k=>traffic.length<2?'':traffic.map((x,i)=>`${30+i*620/(traffic.length-1)},${170-x[k]/tmax*135}`).join(' '),netif=(S.network.interfaces||[]).find(x=>x.status==='Up'&&x.type!=='Loopback'),gate=netif?.gateways?.[0]||'Not reported by Windows';return `<div class="page">${header('Live device statistics','Measured continuously from this computer · new sample every 2 seconds.',`<span class="health">${latest.timestamp?`Updated ${esc(latest.timestamp)}`:'Starting local sampler…'}</span>`)}<div class="notice"><strong>Local host measurements</strong><span>CPU and memory are Windows counters. Traffic is the byte-counter rate for this computer’s adapters. A low rate can mean the computer is idle; it does not measure Internet speed or network capacity.</span></div>${S.live?.error?`<div class="notice warn"><strong>Local sampler unavailable</strong><span>${esc(S.live.error)}</span></div>`:''}<div class="summary-grid"><div class="sum-card"><span>CPU use</span><b>${fmt(latest.cpu_pct)}</b><small>Windows system time deltas</small></div><div class="sum-card"><span>Physical memory</span><b>${fmt(latest.memory_pct)}</b><small>${latest.memory_used_bytes?`${(latest.memory_used_bytes/1073741824).toFixed(1)} / ${(latest.memory_total_bytes/1073741824).toFixed(1)} GB used`:'Waiting for measurement'}</small></div><div class="sum-card"><span>Received</span><b>${rate(rx)}</b><small>all active local adapters</small></div><div class="sum-card"><span>Sent</span><b>${rate(tx)}</b><small>all active local adapters</small></div></div><section class="card"><div class="card-head"><span class="card-title">Local network path</span><span class="card-kicker">OBSERVED / UNKNOWN</span></div><div class="card-body"><div class="path-flow"><div class="path-node"><b>This computer</b><small>source of measured traffic</small></div><span class="path-arrow">→</span><div class="path-node"><b>${esc(netif?.name||'Active adapter')}</b><small>${esc(netif?.description||'OS-reported interface')}</small></div><span class="path-arrow">→</span><div class="path-node"><b>Default gateway</b><small>${esc(gate)} · reported by Windows</small></div><span class="path-arrow">→</span><div class="path-node unknown-node"><b>Internet / destination</b><small>not measured by this local counter</small></div></div><div class="note">The gateway may be a router, modem, or managed network device. This computer cannot identify intermediate hops or their health without controller or path telemetry; no modem nodes are invented.</div></div></section><section class="card" style="margin-top:16px"><div class="card-head"><span class="card-title">CPU and memory trend</span><span class="card-kicker">LAST 20 MINUTES · LOCAL SAMPLE</span></div><div class="card-body">${hist.length>1?`<div class="chart-frame"><svg class="chart-svg live-svg" viewBox="0 0 680 210" role="img" aria-label="CPU and memory use over time"><line x1="30" y1="170" x2="650" y2="170" stroke="#dfe6e9"/><line x1="30" y1="35" x2="30" y2="170" stroke="#dfe6e9"/><polyline points="${pts('cpu_pct')}" fill="none" stroke="#16786e" stroke-width="2.5"/><polyline points="${pts('memory_pct')}" fill="none" stroke="#cb8a42" stroke-width="2.5"/><text x="36" y="25" fill="#16786e">CPU</text><text x="80" y="25" fill="#cb8a42">Memory</text><text x="30" y="38">100%</text><text x="30" y="168">0%</text><text x="30" y="195">${esc(hist[0].timestamp)}</text><text x="530" y="195">${esc(latest.timestamp)}</text></svg></div>`:'<div class="chart-empty">Collecting real measurements. Trend appears after two samples.</div>'}<div class="note">${hist.length} recent samples in memory. The history resets when the local server restarts.</div></div></section><section class="card" style="margin-top:16px"><div class="card-head"><span class="card-title">Traffic flow over time</span><span class="card-kicker">RECEIVE / SEND · LOCAL ADAPTERS</span></div><div class="card-body">${traffic.length>1?`<div class="chart-frame"><svg class="chart-svg live-svg" viewBox="0 0 680 210" role="img" aria-label="Received and sent network traffic over time"><line x1="30" y1="170" x2="650" y2="170" stroke="#dfe6e9"/><line x1="30" y1="35" x2="30" y2="170" stroke="#dfe6e9"/><polyline points="${tpts('rx')}" fill="none" stroke="#16786e" stroke-width="2.5"/><polyline points="${tpts('tx')}" fill="none" stroke="#536bb2" stroke-width="2.5"/><text x="36" y="25" fill="#16786e">Receive</text><text x="105" y="25" fill="#536bb2">Send</text><text x="30" y="38">${rate(tmax)} max</text><text x="30" y="168">0 bps</text><text x="30" y="195">${esc(hist[0].timestamp)}</text><text x="530" y="195">${esc(latest.timestamp)}</text></svg></div>`:'<div class="chart-empty">Collecting adapter counters. Trend appears after two samples.</div>'}<div class="note">Use the graph to see when local traffic rises or settles. “Stable” here describes only the observed traffic rate; it does not mean the Internet path is healthy.</div></div></section><section class="card" style="margin-top:16px"><div class="card-head"><span class="card-title">Per-adapter traffic right now</span><span class="card-kicker">RECEIVE / SEND</span></div>${ifs.length?`<div class="table-wrap"><table class="evidence-table"><thead><tr><th>Interface</th><th>Receive</th><th>Send</th><th>Reported link rate</th></tr></thead><tbody>${ifs.map(x=>`<tr><td><b>${esc(x.name)}</b><br>${esc(x.description)}</td><td>${rate(x.rx_mbps)}</td><td>${rate(x.tx_mbps)}</td><td>${rate(x.speed_mbps)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Waiting for active adapter byte counters.</div>'}<div class="note">Rates are derived from local cumulative byte-counter changes. Link rate is OS-reported adapter speed, not measured Internet capacity.</div></section></div>`}async function init(){await Promise.all([refresh(),loadNetwork(),loadLive()]);if(S.data.cisco?.configured)pollCisco();setInterval(refresh,15000);setInterval(loadNetwork,60000);setInterval(loadLive,2000);setInterval(pollCisco,60000)}init();
